#!/bin/sh
# mkclang22toolchain.sh -- build an EXTERNAL_TOOLCHAIN directory that lets the
# MINIX tree be cross-compiled with a host clang >= 20 instead of the in-tree
# clang 13.
#
# Why: external/apache2/llvm/dist ships clang/lld 13.0.0 sources, but its libcxx
# was bumped to libc++ 22 (_LIBCPP_VERSION 220107), which refuses clang < 20.  So
# the in-tree clang 13 cannot compile any C++ in the tree.  Rather than import a
# full LLVM 22, we drive the build with the host clang 22 as an external
# toolchain, reusing the in-tree binutils (as/ld/objcopy/...) and the libc++ 22
# headers.
#
# Usage:
#   sh mkclang22toolchain.sh -t TOOLDIR -d DESTDIR -o OUTDIR [-c HOSTCLANG]
#
#   TOOLDIR    in-tree tooldir (has bin/x86_64-elf64-minix-{as,ld,objcopy,...})
#   DESTDIR    target sysroot  (build/destdir.amd64)
#   OUTDIR     external toolchain root to create (its bin/ is what you pass as
#              EXTERNAL_TOOLCHAIN)
#   HOSTCLANG  host clang to wrap (default: clang in PATH; must be >= 20)
#
# Then build with:
#   EXTERNAL_TOOLCHAIN=OUTDIR sh build.sh -j16 -mamd64 -O ../build -U -u release
#
# Design notes (see the wrappers below):
#  * COMPILE uses --target=x86_64-elf64-minix so the MINIX predefined macros and
#    the (already MINIX-patched) libc++ 22 platform selection are correct.
#  * LINK uses --target=x86_64-unknown-netbsd: MINIX is a NetBSD derivative
#    (identical crt names, libc layout, ld), and clang's NetBSD driver invokes ld
#    DIRECTLY and honours -nodefaultlibs -- whereas its Minix driver delegates the
#    link to "gcc" and drops -nodefaultlibs, which pulls host libc / breaks the
#    libminc-only MINIX servers.
#  * -B<self> finds the in-tree binutils; -B<destdir>/usr/lib makes
#    `clang --print-file-name=crtbeginS.o` resolve (the in-tree clang baked that
#    path in; stock clang does not).
#  * MINIX installs libc++ headers flat in <sysroot>/usr/include/c++ (not /v1);
#    inject it for C++ unless the caller manages its own dirs (-nostdinc++).

set -e
TOOLDIR=; DESTDIR=; OUTDIR=; HOSTCLANG=clang
TRIPLE=x86_64-elf64-minix
while getopts t:d:o:c: opt; do
	case "$opt" in
	t) TOOLDIR=$OPTARG ;;
	d) DESTDIR=$OPTARG ;;
	o) OUTDIR=$OPTARG ;;
	c) HOSTCLANG=$OPTARG ;;
	*) echo "usage: $0 -t TOOLDIR -d DESTDIR -o OUTDIR [-c HOSTCLANG]" >&2; exit 1 ;;
	esac
done
[ -n "$TOOLDIR" ] && [ -n "$DESTDIR" ] && [ -n "$OUTDIR" ] || {
	echo "usage: $0 -t TOOLDIR -d DESTDIR -o OUTDIR [-c HOSTCLANG]" >&2; exit 1; }

hostclang_path=$(command -v "$HOSTCLANG") || { echo "host clang not found: $HOSTCLANG" >&2; exit 1; }
major=$("$hostclang_path" -dumpversion 2>/dev/null | cut -d. -f1)
[ "${major:-0}" -ge 20 ] 2>/dev/null || echo "warning: host clang ($major) < 20; libc++ 22 wants >= 20" >&2

mkdir -p "$OUTDIR/bin"
# Symlink the in-tree cross binutils (everything except the clang frontends).
# Use a fixed list rather than a glob of $TOOLDIR/bin so this also works before
# the `tools` phase has built them: ln -s happily creates dangling links that
# resolve once the tools exist, and any tool the build never invokes (ld.bfd,
# ld.gold, ...) is harmless if it stays dangling.
for t in addr2line ar as c++filt elfedit install ld ld.bfd ld.gold nm \
         objcopy objdump ranlib readelf size strings strip; do
	ln -sf "$TOOLDIR/bin/${TRIPLE}-$t" "$OUTDIR/bin/${TRIPLE}-$t"
done
# Plain ld/as names so clang's NetBSD link driver finds the cross tools via -B.
ln -sf "${TRIPLE}-ld" "$OUTDIR/bin/ld"
ln -sf "${TRIPLE}-as" "$OUTDIR/bin/as"

# The frontend wrapper (clang / clang++ / clang-cpp dispatch by argv0).
cat > "$OUTDIR/bin/${TRIPLE}-clang" <<EOF
#!/bin/sh
# Generated by mkclang22toolchain.sh -- host clang >= 20 as MINIX cross compiler.
SELF=\$(CDPATH= cd -- "\$(dirname -- "\$0")" && pwd)
DESTROOT=${DESTDIR}
HOSTCLANG=${hostclang_path}
case "\${0##*/}" in
*clang++)   mode=--driver-mode=g++ ;;
*clang-cpp) mode=--driver-mode=cpp ;;
*)          mode= ;;
esac
islink=yes; hassr=no; sr=; nostdinccxx=no
for a in "\$@"; do
	case "\$a" in
	-c|-S|-E|-fsyntax-only|-M|-MM|-dM|-dumpmachine|--version) islink=no ;;
	--print*|-print*) islink=no ;;
	*.c|*.cc|*.cpp|*.cxx|*.C|*.s|*.S|*.i|*.ii|*.m|*.mm) islink=no ;;
	--sysroot=*) sr=\${a#--sysroot=}; hassr=yes ;;
	-nostdinc++) nostdinccxx=yes ;;
	esac
done
sysroot=
[ "\$hassr" = no ] && { sysroot="--sysroot=\${DESTROOT}"; sr=\${DESTROOT}; }
if [ "\$islink" = yes ]; then
	exec "\$HOSTCLANG" \${mode} --target=x86_64-unknown-netbsd \\
		-B"\${SELF}" -B"\${DESTROOT}/usr/lib" \${sysroot} "\$@"
fi
cxxinc=
[ "\${mode}" = "--driver-mode=g++" ] && [ "\$nostdinccxx" = no ] && [ -n "\$sr" ] && \\
	cxxinc="-isystem \${sr}/usr/include/c++"
exec "\$HOSTCLANG" \${mode} --target=x86_64-elf64-minix \\
	-B"\${SELF}" -B"\${DESTROOT}/usr/lib" \${sysroot} \${cxxinc} "\$@"
EOF
chmod +x "$OUTDIR/bin/${TRIPLE}-clang"
ln -sf "${TRIPLE}-clang" "$OUTDIR/bin/${TRIPLE}-clang++"
ln -sf "${TRIPLE}-clang" "$OUTDIR/bin/${TRIPLE}-clang-cpp"

# clang's Minix driver delegates one-shot compile+link to gcc/g++; provide them
# so that delegation also routes through the NetBSD link driver.
cat > "$OUTDIR/bin/gcc" <<EOF
#!/bin/sh
DIR=\$(CDPATH= cd -- "\$(dirname -- "\$0")" && pwd)
exec ${hostclang_path} --target=x86_64-unknown-netbsd --sysroot=${DESTDIR} -B"\$DIR" -B"${DESTDIR}/usr/lib" "\$@"
EOF
cat > "$OUTDIR/bin/g++" <<EOF
#!/bin/sh
DIR=\$(CDPATH= cd -- "\$(dirname -- "\$0")" && pwd)
exec ${hostclang_path} --driver-mode=g++ --target=x86_64-unknown-netbsd --sysroot=${DESTDIR} -B"\$DIR" -B"${DESTDIR}/usr/lib" "\$@"
EOF
chmod +x "$OUTDIR/bin/gcc" "$OUTDIR/bin/g++"

echo "external toolchain ready: $OUTDIR"
echo "build with: EXTERNAL_TOOLCHAIN=$OUTDIR sh build.sh -mamd64 -O ../build -U -u release"
